mapper.select:
select * from  InterfaceSource where sourceType=#{sourceType}

	 and sourceID in (select interfaceSourceID from PortfolioInterfaceMap where portfolio in

			#{item}

	)

select iss.* from InterfaceSource iss, Portfolio_Hdr po, PortfolioInterfaceMap pi where 
iss.sourceID=pi.interfaceSourceID and po.portfolio=pi.portfolio and iss.sourceType=#{sourceType}

	and po.portfolio in

		#{item}


select nvl(max(iis.sourceid),0) from portfoliointerfacemap pim, interfacesource iis  
where pim.interfacesourceid=iis.sourceid and pim.rpSecType=#{rpSecType} and iis.sourceType=#{sourceType} 
and pim.portfolio=#{portnum} and rownum=1
